import React from "react";
import { Link } from "@tanstack/react-router";
import { getResponsiveSrcSet } from "../../utils/imageHelpers";

// Swiper
import { Swiper, SwiperSlide } from "swiper/react";
import "swiper/css";
import "swiper/css/pagination";
import { Autoplay, Pagination } from "swiper";

// Classes
import { displayHeading } from "../lib/Classes";

// Components
import DefaultProductShown from "./DefaultProductShown";
import LikeShare from "./LikeShare";
import Stars from "./Stars";

const DisplayedProduct = React.memo(({ productShown, data }) => {
  if (productShown === -1) {
    return <DefaultProductShown />;
  }

  return (
    <div className="min-w-[300px] w-[300px] max-h-[680px] hidden lg:block overflow-hidden border-[3px] border-[#E1E1E1] drop-shadow shadow-[0px_4px_20px_rgba(166,166,166,0.3)] rounded-[10px] bg-white">
      <Swiper
        spaceBetween={30}
        centeredSlides={true}
        autoplay={{
          delay: 3500,
          disableOnInteraction: true,
        }}
        pagination={{ clickable: true }}
        modules={[Autoplay, Pagination]}
        className="mySwiper CategoryProducts"
      >
        {data.products.map((product, index) => {
          return (
            <SwiperSlide key={index} className="overflow-visible h-fit">
              <div className="flex justify-between items-center">
                <p
                  className={`text-start ${displayHeading} ml-[15px] w-[14rem] discriptionTruncate-1`}
                  title={product[0]}
                >
                  {product[0]}
                </p>
                <div className="right-[15px] relative">
                  <LikeShare
                    liked={product[3]}
                    title={product[0]}
                    link={product[0].replace(/ /g, "-")}
                    image={product[1] ? ((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + product[1]) : ""}
                  />
                </div>
              </div>
              <div className="ml-[18px]">
                <Stars rating={product[5]} stars={product[4]} />
              </div>

              <div className="flex justify-center items-center !w-[40%] h-[20%] m-auto">
                <img
                  className="!w-[161.58px] !h-[170px] m-auto pb-[12px] object-contain"
                  src={product[1] ? ((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + product[1]) : ""}
                  srcSet={product[1] ? getResponsiveSrcSet((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + product[1]) : ""}
                  sizes="300px"
                  alt={product[0]}
                  title={product[0]}
                  loading="lazy"
                />
              </div>

              {/*
                Use dangerouslySetInnerHTML instead of html-react-parser's parse().
                parse() recursively reconstructs the DOM in JS — if the backend returns
                a full HTML document (<html><body>...) it overflows the call stack.
                The browser's native HTML parser handles this safely and efficiently.
              */}
              <div
                className="font-poppins font-normal text-[16px] leading-[22.96px] tracking-[2%] text-[#004B95] discriptionTruncate-15 h-[300px] mb-3 px-5"
                dangerouslySetInnerHTML={{ __html: product[2] }}
              />

              {/* Link wraps button — <a> inside <button> is invalid HTML */}
              <Link
                to={"/product/" + product[0].replace(/ /g, "-")}
                preload="intent"
                aria-label={`Read more about ${product[0]}`}
              >
                <button className="relative text-center mb-8 font-poppins font-semibold text-[#FFFFFF] bg-[#004B95] w-[88%] px-3 h-[50px] rounded-[5px] text-[20px] leading-[40.8px] tracking-[5%] left-[20px]">
                  Read More <span className="sr-only">about {product[0]}</span>
                </button>
              </Link>
            </SwiperSlide>
          );
        })}
      </Swiper>
    </div>
  );
});

export default DisplayedProduct;
