import React, { useState, useEffect } from "react";
import axios from "axios";

// Swiper
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, EffectCoverflow } from "swiper";
import "swiper/css";
import "swiper/css/autoplay";
import "swiper/css/effect-coverflow";

// Styles
import "../Product_Video/productvideo.css";
// Image
import Background from "../assets/images/Rectangle20.webp";

const ProductVideos = () => {
  const [videos, setVideos] = useState([]);

  // Fetch YouTube video data
  useEffect(() => {
    const fetchVideos = async () => {
      try {
        const response = await axios.get(
          (process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + "/api/youtubeVideoList/"
        );
        if (response.data && response.data.data) {
          setVideos(response.data.data);
        }
      } catch (error) {
        console.error("Error fetching product videos:", error);
      }
    };
    fetchVideos();
  }, []);

  // Helper function to ensure YouTube URLs are in embed format
  const getEmbedUrl = (url) => {
    if (!url) return "";
    if (url.includes("embed")) return url;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    if (match && match[2].length === 11) {
      return `https://www.youtube.com/embed/${match[2]}`;
    }
    return url;
  };

  return (
    <div className="py-10">
      {/* Heading */}
      <div className="box h-[5rem] w-[25rem] relative flex justify-start items-start ml-[2rem] group mt-6 ">
        <div className="h-12 w-1.5 bg-[#004B95] absolute mr-[1rem] origin-left group-hover:w-[18rem] duration-300 group"></div>
        <p className="text-[24px] absolute font-bold text-[#004B95] mt-[0.5rem] ml-[1rem] group-hover:text-white group-hover:translate-x-5 duration-300">
          Product Videos
        </p>
      </div>

      {/* Youtube video slider container */}
      <div
        className="product-video-wrapper w-full flex items-center justify-center bg-no-repeat bg-cover bg-center"
        style={{
          backgroundImage: `url(${Background})`,
          minHeight: "450px",
        }}
      >
        {videos.length > 0 ? (
          <Swiper
            effect="coverflow"
            grabCursor={true}
            centeredSlides={true}
            loop={videos.length >= 3}
            autoplay={{
              delay: 5000,
              disableOnInteraction: false,
            }}
            coverflowEffect={{
              rotate: 30,
              stretch: 0,
              depth: 100,
              modifier: 1,
              slideShadows: false,
            }}
            breakpoints={{
              320: { slidesPerView: 1 },
              640: { slidesPerView: 2 },
              1024: { slidesPerView: 3 },
            }}
            modules={[EffectCoverflow, Autoplay]}
            className="mySwiper w-full py-10"
          >
            {videos.map((item, index) => (
              <SwiperSlide key={index} className="flex flex-col items-center">
                <div className="w-[95%] mx-auto bg-black/20 backdrop-blur-sm rounded-2xl overflow-hidden shadow-2xl border border-white/10 group/card">
                  <div className="relative aspect-video">
                    <iframe
                      className="w-full h-full"
                      src={getEmbedUrl(item[1])}
                      loading="lazy"
                      title={item[0]}
                      frameBorder="0"
                      referrerPolicy="strict-origin-when-cross-origin"
                      allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                      allowFullScreen
                    ></iframe>
                  </div>
                  <div className="p-4 bg-gradient-to-t from-black/80 to-transparent">
                    <h3 className="font-bold text-white text-center truncate px-2" title={item[0]}>
                      {item[0]}
                    </h3>
                  </div>
                </div>
              </SwiperSlide>
            ))}
          </Swiper>
        ) : (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#004B95]"></div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductVideos;
