import React, { useRef, useState, useEffect } from "react";

/**
 * LazySection — only mounts children once the placeholder scrolls into view.
 * Uses IntersectionObserver with a rootMargin so the section starts loading
 * slightly before the user reaches it (no visible pop-in).
 *
 * @param {string} minHeight  - Reserve space before mounting to prevent layout shift
 * @param {string} rootMargin - How far before viewport to start loading (default 300px)
 */
const LazySection = ({ children, minHeight = "200px", rootMargin = "300px" }) => {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // If IntersectionObserver is not supported, just show it immediately
    if (!window.IntersectionObserver) {
      setVisible(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect(); // only need to fire once
        }
      },
      { rootMargin }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [rootMargin]);

  return (
    <div ref={ref} style={!visible ? { minHeight } : undefined}>
      {visible ? children : null}
    </div>
  );
};

export default LazySection;
